	"fmt"
	"math"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, c1, c2 int
	fmt.Fscanf(reader, "%d %d %d", &n, &c1, &c2)

	s := make([]byte, n)
	reader.Read(s)
	// Read the rest of the line if needed
	buf := make([]byte, 1)
	reader.Read(buf)

	// Count adults and pupils
	adults := 0
	pupils := 0
	for i := 0; i < n; i++ {
		if s[i] == '1' {
			adults++
		} else {
			pupils++
		}
	}

	// We need to partition n people into groups, each with at least 1 adult.
	// Let k be the number of groups. Then k <= adults.
	// Each group has at least 1 adult.
	// The total number of people is n.
	// We want to minimize sum over groups of c1 + c2*(x_i - 1)^2
	// where x_i is the size of group i, and sum x_i = n.
	//
	// Let's think about it differently.
	// We have 'adults' adults and 'pupils' pupils.
	// We form k groups (1 <= k <= adults).
	// Each group must have at least 1 adult.
	// Let a_i be the number of adults in group i, p_i be the number of pupils in group i.
	// a_i >= 1, p_i >= 0, sum a_i = adults, sum p_i = pupils.
	// Group size x_i = a_i + p_i.
	// Cost = sum (c1 + c2*(x_i - 1)^2) = k*c1 + c2 * sum (x_i - 1)^2.
	//
	// We need to minimize sum (x_i - 1)^2 subject to:
	// x_i >= 1, sum x_i = n, and each group has at least 1 adult.
	//
	// Since each group has at least 1 adult, the minimum possible x_i is 1 (if the group has 1 adult and 0 pupils).
	//
	// Let's reframe: we have n people to distribute into k groups.
	// The constraint is that each group has at least 1 adult.
	// This means that if we assign adults first, each group gets at least 1 adult.
	// The remaining (adults - k) adults and all pupils can be distributed freely.
	//
	// Actually, the key insight is:
	// For a fixed k (number of groups), what is the minimum sum of (x_i - 1)^2?
	// We have n people in k groups, so sum x_i = n.
	// Let y_i = x_i - 1, so y_i >= 0 and sum y_i = n - k.
	// We want to minimize sum y_i^2.
	//
	// But wait, there's a constraint: each group must have at least 1 adult.
	// This means that x_i >= 1 is already satisfied.
	// But does the adult constraint impose any additional restriction on the distribution of x_i?
	//
	// Let's think: if we have k groups and adults >= k, we can always assign at least 1 adult to each group.
	// The remaining adults and pupils can be distributed arbitrarily.
	// So the only constraint on x_i is that x_i >= 1 and sum x_i = n.
	//
	// Wait, that's not quite right. The constraint is that each group has at least 1 adult.
	// This means that the number of adults in group i, a_i, must be >= 1.
	// And a_i <= x_i (since x_i = a_i + p_i).
	// So we need a_i >= 1 for all i, which means x_i >= a_i >= 1.
	// But x_i can be larger than a_i if there are pupils.
	//
	// The key is: for a given k, can we always achieve any distribution of x_i where x_i >= 1 and sum x_i = n?
	// Yes, as long as adults >= k. Because we can assign 1 adult to each group, and then distribute the remaining (adults - k) adults and all pupils to make the group sizes x_i.
	//
	// So for a fixed k (1 <= k <= adults), the minimum sum of (x_i - 1)^2 is achieved when the x_i are as equal as possible.
	//
	// Let n = k * q + r, where 0 <= r < k.
	// Then r groups have size q+1, and k-r groups have size q.
	// Sum (x_i - 1)^2 = r*(q)^2 + (k-r)*(q-1)^2.
	//
	// Wait, x_i - 1: if x_i = q+1, then x_i - 1 = q. If x_i = q, then x_i - 1 = q-1.
	// So sum = r*q^2 + (k-r)*(q-1)^2.
	//
	// Total cost for k groups: k*c1 + c2*(r*q^2 + (k-r)*(q-1)^2).
	//
	// We need to minimize this over k from 1 to adults.
	//
	// Let's verify with the examples.
	//
	// Example 1: n=3, c1=4, c2=1, s="011" -> adults=2, pupils=1.
	// k can be 1 or 2.
	// k=1: n=3, q=3, r=0. Sum = 0*9 + 1*(3-1)^2 = 4. Cost = 1*4 + 1*4 = 8.
	// k=2: n=3, q=1, r=1. Sum = 1*1^2 + 1*0^2 = 1. Cost = 2*4 + 1*1 = 9.
	// Min is 8. Correct.
	//
	// Example 2: n=4, c1=7, c2=2, s="1101" -> adults=3, pupils=1.
	// k can be 1, 2, or 3.
	// k=1: n=4, q=4, r=0. Sum = 1*(4-1)^2 = 9. Cost = 1*7 + 2*9 = 25.
	// k=2: n=4, q=2, r=0. Sum = 2*(2-1)^2 = 2. Cost = 2*7 + 2*2 = 18.
	// k=3: n=4, q=1, r=1. Sum = 1*1^2 + 2*0^2 = 1. Cost = 3*7 + 2*1 = 23.
	// Min is 18. Correct.
	//
	// So the algorithm is:
	// For k from 1 to adults:
	//   q = n / k
	//   r = n % k
	//   sum_sq = r * q * q + (k - r) * (q - 1) * (q - 1)
	//   cost = k * c1 + c2 * sum_sq
	//   track minimum cost.
	//
	// But n can be up to 200,000 and adults can be up to 200,000, so iterating over all k is O(n) which is fine.

	minCost := int64(math.MaxInt64)
	for k := 1; k <= adults; k++ {
		q := n / k
		r := n % k
		// sum_sq = r * q^2 + (k - r) * (q - 1)^2
		sum_sq := int64(r)*int64(q)*int64(q) + int64(k-r)*int64(q-1)*int64(q-1)
		cost := int64(k)*int64(c1) + int64(c2)*sum_sq
		if cost < minCost {
			minCost = cost
		}
	}

	fmt.Println(minCost)
}
