		base := n / k
		rem := n % k
		// rem groups have size base+1, (k-rem) groups have size base
		// (xi-1) for size base+1 is base
		// (xi-1) for size base is base-1
		sumSq := int64(rem)*int64(base)*int64(base) + int64(k-rem)*int64(base-1)*int64(base-1)
